// @FIGURE_CODE_BEGIN
// 1) Define geometric constants and colors
const colorBlue = 0x7BAFD4;
const colorOrange = 0xF5B041;
const colorRed = 0xD62728;
const colorGreen = 0x2CA02C;
const colorDarkOrange = 0xF58231;

// 2) Basic thick arrow generator
function createThickArrow(color, baseRadius=0.06, headRadius=0.15, headLength=0.4) {
  const group = new THREE.Group();
  const mat = new THREE.MeshPhongMaterial({ color, shininess: 60 });
  const cyl = new THREE.Mesh(new THREE.CylinderGeometry(baseRadius, baseRadius, 1, 12), mat);
  const head = new THREE.Mesh(new THREE.ConeGeometry(headRadius, headLength, 12), mat);
  cyl.rotation.x = Math.PI / 2;
  cyl.position.set(0, 0, 0.5);
  head.rotation.x = Math.PI / 2;
  head.position.set(0, 0, 1);
  group.add(cyl);
  group.add(head);

  group.update = function(origin, dir, length) {
    if (length < 0.001) {
      this.visible = false;
      return;
    }
    this.visible = true;
    this.position.copy(origin);
    const q = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0,0,1), dir.clone().normalize());
    this.quaternion.copy(q);

    const cylLen = Math.max(0, length - headLength);
    cyl.scale.set(1, cylLen, 1);
    cyl.position.set(0, 0, cylLen / 2);
    head.position.set(0, 0, cylLen + headLength / 2);
  };
  return group;
}

function makeInteractive(arrowGroup, info) {
  arrowGroup.children.forEach(c => registerInteractive(c, info));
}

// 3) Setup Lights
const ambientLight = new THREE.AmbientLight(0xffffff, 0.7);
scene.add(ambientLight);
const dirLight = new THREE.DirectionalLight(0xffffff, 0.5);
dirLight.position.set(10, 15, 10);
scene.add(dirLight);
const dirLight2 = new THREE.DirectionalLight(0xffffff, 0.3);
dirLight2.position.set(-10, 5, -10);
scene.add(dirLight2);

// 4) Construct Top Geometry
const ptsBlue1 = [], ptsOrange = [], ptsBlue2 = [];
for (let i = 0; i <= 15; i++) {
  const y = i * 0.1; 
  ptsBlue1.push(new THREE.Vector2(2.5 - 0.4 * Math.pow(y - 2.5, 2), y));
}
for (let i = 15; i <= 28; i++) {
  const y = i * 0.1;
  ptsOrange.push(new THREE.Vector2(2.5 - 0.4 * Math.pow(y - 2.5, 2), y));
}
for (let i = 28; i <= 40; i++) {
  const y = i * 0.1;
  ptsBlue2.push(new THREE.Vector2(2.5 - 0.4 * Math.pow(y - 2.5, 2), y));
}

const matBlue = new THREE.MeshPhongMaterial({ color: colorBlue, shininess: 60 });
const matOrange = new THREE.MeshPhongMaterial({ color: colorOrange, shininess: 60 });

const topGroup = new THREE.Group();
const meshBlue1 = new THREE.Mesh(new THREE.LatheGeometry(ptsBlue1, 32), matBlue);
const meshOrange = new THREE.Mesh(new THREE.LatheGeometry(ptsOrange, 32), matOrange);
const meshBlue2 = new THREE.Mesh(new THREE.LatheGeometry(ptsBlue2, 32), matBlue);
const meshStem = new THREE.Mesh(new THREE.CylinderGeometry(0.4, 0.4, 1.5, 32), matBlue);
meshStem.position.set(0, 4.75, 0);
topGroup.add(meshBlue1, meshOrange, meshBlue2, meshStem);

// CM Marker (X)
const cmMarker = new THREE.Group();
const matBlack = new THREE.LineBasicMaterial({ color: 0x000000, linewidth: 2 });
cmMarker.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints([
  new THREE.Vector3(-0.3, 3, -0.3), new THREE.Vector3(0.3, 3, 0.3)
]), matBlack));
cmMarker.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints([
  new THREE.Vector3(-0.3, 3, 0.3), new THREE.Vector3(0.3, 3, -0.3)
]), matBlack));
topGroup.add(cmMarker);

// Omega (spin) arrow around stem
const omegaGroup = new THREE.Group();
const omegaCurvePts = [];
for (let i = 0; i <= 20; i++) {
  const a = -Math.PI/2 + (i/20) * Math.PI * 1.5;
  omegaCurvePts.push(new THREE.Vector3(1.1 * Math.cos(a), 4.75, 1.1 * Math.sin(a)));
}
const omegaTube = new THREE.Mesh(new THREE.TubeGeometry(new THREE.CatmullRomCurve3(omegaCurvePts), 20, 0.04, 8, false), new THREE.MeshBasicMaterial({ color: colorGreen }));
const omegaHead = new THREE.Mesh(new THREE.ConeGeometry(0.12, 0.3, 8), new THREE.MeshBasicMaterial({ color: colorGreen }));
omegaHead.position.copy(omegaCurvePts[20]);
omegaHead.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0), omegaCurvePts[20].clone().sub(omegaCurvePts[19]).normalize());
omegaGroup.add(omegaTube, omegaHead);
topGroup.add(omegaGroup);

// Make top interactive
[meshBlue1, meshOrange, meshBlue2, meshStem].forEach(m => registerInteractive(m, { 
  title: "Spinning Top", 
  body: "The fast spin provides a large angular momentum L, which resists falling over." 
}));

// 5) Setup Scene Hierarchy and Elements
const precessionGroup = new THREE.Group();
scene.add(precessionGroup);
precessionGroup.add(topGroup);

const arrR = createThickArrow(0x000000, 0.05, 0.12, 0.4); precessionGroup.add(arrR);
const arrMg = createThickArrow(colorRed, 0.06, 0.15, 0.5); precessionGroup.add(arrMg);
const arrTau = createThickArrow(colorDarkOrange, 0.06, 0.15, 0.5); precessionGroup.add(arrTau);
const arrL = createThickArrow(colorDarkOrange, 0.06, 0.15, 0.5); precessionGroup.add(arrL);
const arrLSin = createThickArrow(colorDarkOrange, 0.05, 0.12, 0.4); precessionGroup.add(arrLSin);
const arrDL = createThickArrow(colorDarkOrange, 0.05, 0.12, 0.4); precessionGroup.add(arrDL);

makeInteractive(arrR, { title: "Position Vector (r)", body: "Vector from the origin to the center of mass (CM)." });
makeInteractive(arrMg, { title: "Gravitational Force (Mg)", body: "The downward pull of gravity acting on the CM." });
makeInteractive(arrTau, { title: "Torque (τ)", body: "The twisting force caused by gravity. It acts perpendicularly to both r and Mg." });
makeInteractive(arrL, { title: "Angular Momentum (L)", body: "The rotational momentum of the top. It aligns with the spin axis." });
makeInteractive(arrDL, { title: "Change in Angular Momentum (dL)", body: "Because the torque is perpendicular to L, it changes the direction of L without changing its magnitude." });

// Dashed circle and arcs
const dashedMat = new THREE.LineDashedMaterial({ color: 0x000000, dashSize: 0.2, gapSize: 0.2 });
const circlePts = [];
for (let i = 0; i <= 64; i++) {
  const a = (i/64) * Math.PI * 2;
  circlePts.push(new THREE.Vector3(Math.cos(a), 0, Math.sin(a)));
}
const circleLine = new THREE.Line(new THREE.BufferGeometry().setFromPoints(circlePts), dashedMat);
circleLine.computeLineDistances();
scene.add(circleLine);

const futureRadLine = new THREE.Line(new THREE.BufferGeometry(), dashedMat); precessionGroup.add(futureRadLine);
const thetaArcLine = new THREE.Line(new THREE.BufferGeometry(), new THREE.LineBasicMaterial({ color: 0x000000 })); precessionGroup.add(thetaArcLine);
const dPhiArcLine = new THREE.Line(new THREE.BufferGeometry(), new THREE.LineBasicMaterial({ color: 0x000000 })); precessionGroup.add(dPhiArcLine);

const omegaPGroup = new THREE.Group();
const omegaPHead = new THREE.Mesh(new THREE.ConeGeometry(0.12, 0.3, 8), new THREE.MeshBasicMaterial({ color: 0x000000 }));
omegaPGroup.add(omegaPHead);
precessionGroup.add(omegaPGroup);

const leaderGroup = new THREE.Group();
const leaderLine = new THREE.Line(new THREE.BufferGeometry(), new THREE.LineBasicMaterial({ color: 0x000000 }));
const leaderHead = new THREE.Mesh(new THREE.ConeGeometry(0.08, 0.2, 8), new THREE.MeshBasicMaterial({ color: 0x000000 }));
leaderGroup.add(leaderLine, leaderHead);
scene.add(leaderGroup);

// Stationary Axes
const axisX = createThickArrow(0x000000, 0.02, 0.08, 0.2); scene.add(axisX); axisX.update(new THREE.Vector3(), new THREE.Vector3(1,0,0), 8);
const axisY = createThickArrow(0x000000, 0.02, 0.08, 0.2); scene.add(axisY); axisY.update(new THREE.Vector3(), new THREE.Vector3(0,1,0), 8);
const axisZ = createThickArrow(0x000000, 0.02, 0.08, 0.2); scene.add(axisZ); axisZ.update(new THREE.Vector3(), new THREE.Vector3(0,0,1), 8);

// 6) State variables and logic
let thetaDeg = 20;
let torqueMag = 1;
let phiDeg = 60;
let isPlaying = false;
let omegaPTubeMesh = null;

function rebuildGeometry() {
  const thetaRad = THREE.MathUtils.degToRad(thetaDeg);

  // u_local tilts away from Y axis towards +Z in the local frame
  const u_local = new THREE.Vector3(0, Math.cos(thetaRad), Math.sin(thetaRad));
  topGroup.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0), u_local);

  const cmPos_local = u_local.clone().multiplyScalar(3);
  arrR.update(new THREE.Vector3(0,0,0), u_local, 3);
  arrMg.update(cmPos_local, new THREE.Vector3(0,-1,0), 2);

  // tau = r x Mg. (0, cy, sz) x (0, -1, 0) = (sz, 0, 0) => local +X
  const tauDir_local = new THREE.Vector3(1, 0, 0);
  const tauLen = 6 * Math.sin(thetaRad) * torqueMag;
  arrTau.update(cmPos_local, tauDir_local, tauLen);

  arrL.update(cmPos_local, u_local, 8);

  const lTip_local = cmPos_local.clone().add(u_local.clone().multiplyScalar(8));
  const circleCenter_local = new THREE.Vector3(0, lTip_local.y, 0);
  const rad = lTip_local.z;

  circleLine.position.set(0, lTip_local.y, 0);
  circleLine.scale.set(rad, 1, rad);

  const radDir_local = new THREE.Vector3(0, 0, 1);
  arrLSin.update(circleCenter_local, radDir_local, rad);

  const dLLen = 4.5 * torqueMag * Math.sin(thetaRad);
  arrDL.update(lTip_local, tauDir_local, dLLen);

  const lTipFuture_local = lTip_local.clone().add(tauDir_local.clone().multiplyScalar(dLLen));
  futureRadLine.geometry.setFromPoints([circleCenter_local, lTipFuture_local]);
  futureRadLine.computeLineDistances();

  const dPhiPts = [];
  const startAngle = Math.atan2(lTip_local.z, lTip_local.x);
  const endAngle = Math.atan2(lTipFuture_local.z, lTipFuture_local.x);
  for(let i=0; i<=10; i++){
    const a = startAngle + (i/10)*(endAngle - startAngle);
    dPhiPts.push(new THREE.Vector3(rad*Math.cos(a), lTip_local.y, rad*Math.sin(a)));
  }
  dPhiArcLine.geometry.setFromPoints(dPhiPts);

  const thPts = [];
  for(let i=0; i<=10; i++){
    const t = (i/10)*thetaRad;
    thPts.push(new THREE.Vector3(0, 2.5*Math.cos(t), 2.5*Math.sin(t)));
  }
  thetaArcLine.geometry.setFromPoints(thPts);

  // omega_p arc on the back of the circle
  const opRadius = rad + 0.8;
  const opStart = Math.PI * 1.7;
  const opEnd = Math.PI * 1.3;
  const opPts = [];
  for(let i=0; i<=20; i++){
    const a = opStart + (i/20)*(opEnd - opStart);
    opPts.push(new THREE.Vector3(opRadius*Math.cos(a), lTip_local.y, opRadius*Math.sin(a)));
  }
  if(omegaPTubeMesh) omegaPGroup.remove(omegaPTubeMesh);
  omegaPTubeMesh = new THREE.Mesh(new THREE.TubeGeometry(new THREE.CatmullRomCurve3(opPts), 20, 0.04, 8, false), new THREE.MeshBasicMaterial({ color: 0x000000 }));
  omegaPGroup.add(omegaPTubeMesh);
  omegaPHead.position.copy(opPts[20]);
  omegaPHead.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0), opPts[20].clone().sub(opPts[19]).normalize());

  window.__sceneData = { cmPos_local, lTip_local, lTipFuture_local, circleCenter_local, rad, tauDir_local, dLLen, opRadius, opStart, opEnd };
}

// 7) Label Definitions and Updates
let lblX, lblY, lblZ, lblO, lblTheta, lblR, lblCM, lblMg, lblTau, lblTauEq, lblOmega, lblL, lblLSin, lblDL, lblDPhi, lblOmegaP;

function initLabels() {
  lblX = addLabel('<i>y</i>', new THREE.Vector3(), { color: '#000' });
  lblY = addLabel('<i>z</i>', new THREE.Vector3(), { color: '#000' });
  lblZ = addLabel('<i>x</i>', new THREE.Vector3(), { color: '#000' });
  lblO = addLabel('<i>O</i>', new THREE.Vector3(), { color: '#000' });
  lblTheta = addLabel('<i>&theta;</i>', new THREE.Vector3(), { color: '#000' });
  lblR = addLabel('<b>r</b>', new THREE.Vector3(), { color: '#000' });
  lblCM = addLabel('CM', new THREE.Vector3(), { color: '#000' });
  lblMg = addLabel('<i>M</i><b>g</b>', new THREE.Vector3(), { color: '#' + colorRed.toString(16).padStart(6, '0') });
  lblTau = addLabel('<b>&tau;</b>', new THREE.Vector3(), { color: '#' + colorDarkOrange.toString(16).padStart(6, '0') });
  lblTauEq = addLabel('<b>&tau;</b> = <b>r</b> &times; <i>M</i><b>g</b>', new THREE.Vector3(), { color: '#000' });
  lblOmega = addLabel('<b>&omega;</b>', new THREE.Vector3(), { color: '#' + colorGreen.toString(16).padStart(6, '0') });
  lblL = addLabel('<b>L</b>', new THREE.Vector3(), { color: '#' + colorDarkOrange.toString(16).padStart(6, '0') });
  lblLSin = addLabel('<i>L</i> sin <i>&theta;</i>', new THREE.Vector3(), { color: '#000' });
  lblDL = addLabel('<i>d</i><b>L</b> = <b>&tau;</b> <i>dt</i>', new THREE.Vector3(), { color: '#000' });
  lblDPhi = addLabel('<i>d&phi;</i>', new THREE.Vector3(), { color: '#000' });
  lblOmegaP = addLabel('<b>&omega;</b><sub><i>p</i></sub>', new THREE.Vector3(), { color: '#000' });
}

function updateLabels() {
  precessionGroup.rotation.y = THREE.MathUtils.degToRad(phiDeg);
  precessionGroup.updateMatrixWorld();

  lblX.pos.set(8.5, 0, 0);
  lblY.pos.set(0, 8.5, 0);
  lblZ.pos.set(0, 0, 8.5);
  lblO.pos.set(0, -0.5, 0);

  const d = window.__sceneData;
