// 6) State variables and logic
let thetaDeg = 20;
let torqueMag = 1;
let phiDeg = 60;
let isPlaying = false;
let omegaPTubeMesh = null;

function rebuildGeometry() {
  const thetaRad = THREE.MathUtils.degToRad(thetaDeg);

  // u_local tilts away from Y axis towards +Z in the local frame
  const u_local = new THREE.Vector3(0, Math.cos(thetaRad), Math.sin(thetaRad));
  topGroup.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0), u_local);

  const cmPos_local = u_local.clone().multiplyScalar(3);
  arrR.update(new THREE.Vector3(0,0,0), u_local, 3);
  arrMg.update(cmPos_local, new THREE.Vector3(0,-1,0), 2);

  // tau = r x Mg. (0, cy, sz) x (0, -1, 0) = (sz, 0, 0) => local +X
  const tauDir_local = new THREE.Vector3(1, 0, 0);
  const tauLen = 6 * Math.sin(thetaRad) * torqueMag;
  arrTau.update(cmPos_local, tauDir_local, tauLen);

  arrL.update(cmPos_local, u_local, 8);

  const lTip_local = cmPos_local.clone().add(u_local.clone().multiplyScalar(8));
  const circleCenter_local = new THREE.Vector3(0, lTip_local.y, 0);
  const rad = lTip_local.z;

  circleLine.position.set(0, lTip_local.y, 0);
  circleLine.scale.set(rad, 1, rad);

  const radDir_local = new THREE.Vector3(0, 0, 1);
  arrLSin.update(circleCenter_local, radDir_local, rad);

  const dLLen = 4.5 * torqueMag * Math.sin(thetaRad);
  arrDL.update(lTip_local, tauDir_local, dLLen);

  const lTipFuture_local = lTip_local.clone().add(tauDir_local.clone().multiplyScalar(dLLen));
  futureRadLine.geometry.setFromPoints([circleCenter_local, lTipFuture_local]);
  futureRadLine.computeLineDistances();

  const dPhiPts = [];
  const startAngle = Math.atan2(lTip_local.z, lTip_local.x);
  const endAngle = Math.atan2(lTipFuture_local.z, lTipFuture_local.x);
  for(let i=0; i<=10; i++){
    const a = startAngle + (i/10)*(endAngle - startAngle);
    dPhiPts.push(new THREE.Vector3(rad*Math.cos(a), lTip_local.y, rad*Math.sin(a)));
  }
  dPhiArcLine.geometry.setFromPoints(dPhiPts);

  const thPts = [];
  for(let i=0; i<=10; i++){
    const t = (i/10)*thetaRad;
    thPts.push(new THREE.Vector3(0, 2.5*Math.cos(t), 2.5*Math.sin(t)));
  }
  thetaArcLine.geometry.setFromPoints(thPts);

  // omega_p arc on the back of the circle
  const opRadius = rad + 0.8;
  const opStart = Math.PI * 1.7;
  const opEnd = Math.PI * 1.3;
  const opPts = [];
  for(let i=0; i<=20; i++){
    const a = opStart + (i/20)*(opEnd - opStart);
    opPts.push(new THREE.Vector3(opRadius*Math.cos(a), lTip_local.y, opRadius*Math.sin(a)));
  }
  if(omegaPTubeMesh) omegaPGroup.remove(omegaPTubeMesh);
  omegaPTubeMesh = new THREE.Mesh(new THREE.TubeGeometry(new THREE.CatmullRomCurve3(opPts), 20, 0.04, 8, false), new THREE.MeshBasicMaterial({ color: 0x000000 }));
  omegaPGroup.add(omegaPTubeMesh);
  omegaPHead.position.copy(opPts[20]);
  omegaPHead.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0), opPts[20].clone().sub(opPts[19]).normalize());

  window.__sceneData = { cmPos_local, lTip_local, lTipFuture_local, circleCenter_local, rad, tauDir_local, dLLen, opRadius, opStart, opEnd };
}

// 7) Label Definitions and Updates
let lblX, lblY, lblZ, lblO, lblTheta, lblR, lblCM, lblMg, lblTau, lblTauEq, lblOmega, lblL, lblLSin, lblDL, lblDPhi, lblOmegaP;

function initLabels() {
  lblX = addLabel('<i>y</i>', new THREE.Vector3(), { color: '#000' });
  lblY = addLabel('<i>z</i>', new THREE.Vector3(), { color: '#000' });
  lblZ = addLabel('<i>x</i>', new THREE.Vector3(), { color: '#000' });
  lblO = addLabel('<i>O</i>', new THREE.Vector3(), { color: '#000' });
  lblTheta = addLabel('<i>&theta;</i>', new THREE.Vector3(), { color: '#000' });
  lblR = addLabel('<b>r</b>', new THREE.Vector3(), { color: '#000' });
  lblCM = addLabel('CM', new THREE.Vector3(), { color: '#000' });
  lblMg = addLabel('<i>M</i><b>g</b>', new THREE.Vector3(), { color: '#' + colorRed.toString(16).padStart(6, '0') });
  lblTau = addLabel('<b>&tau;</b>', new THREE.Vector3(), { color: '#' + colorDarkOrange.toString(16).padStart(6, '0') });
  lblTauEq = addLabel('<b>&tau;</b> = <b>r</b> &times; <i>M</i><b>g</b>', new THREE.Vector3(), { color: '#000' });
  lblOmega = addLabel('<b>&omega;</b>', new THREE.Vector3(), { color: '#' + colorGreen.toString(16).padStart(6, '0') });
  lblL = addLabel('<b>L</b>', new THREE.Vector3(), { color: '#' + colorDarkOrange.toString(16).padStart(6, '0') });
  lblLSin = addLabel('<i>L</i> sin <i>&theta;</i>', new THREE.Vector3(), { color: '#000' });
  lblDL = addLabel('<i>d</i><b>L</b> = <b>&tau;</b> <i>dt</i>', new THREE.Vector3(), { color: '#000' });
  lblDPhi = addLabel('<i>d&phi;</i>', new THREE.Vector3(), { color: '#000' });
  lblOmegaP = addLabel('<b>&omega;</b><sub><i>p</i></sub>', new THREE.Vector3(), { color: '#000' });
}

function updateLabels() {
  precessionGroup.rotation.y = THREE.MathUtils.degToRad(phiDeg);
  precessionGroup.updateMatrixWorld();

  lblX.pos.set(8.5, 0, 0);
  lblY.pos.set(0, 8.5, 0);
  lblZ.pos.set(0, 0, 8.5);
  lblO.pos.set(0, -0.5, 0);

  const d = window.__sceneData;
  if (!d) return;

  const toWorld = (v) => v.clone().applyMatrix4(precessionGroup.matrixWorld);

  const cmPos = toWorld(d.cmPos_local);
  const lTip = toWorld(d.lTip_local);
  const lTipFuture = toWorld(d.lTipFuture_local);
  const circleCenter = toWorld(d.circleCenter_local);

  lblR.pos.copy(cmPos).multiplyScalar(0.5).add(new THREE.Vector3(0.2, 0, 0.2));
  lblCM.pos.copy(cmPos).add(new THREE.Vector3(-0.6, 0.2, -0.6));
  lblMg.pos.copy(cmPos).add(new THREE.Vector3(0, -1.2, 0));

  const tauDir = toWorld(d.tauDir_local).sub(toWorld(new THREE.Vector3())).normalize();
  lblTau.pos.copy(cmPos).add(tauDir.clone().multiplyScalar(1.5)).add(new THREE.Vector3(0, 0.4, 0));
  lblTauEq.pos.copy(cmPos).add(new THREE.Vector3(4, -1, 0));

  const leaderStart = lblTauEq.pos.clone().add(new THREE.Vector3(-0.5, 0.2, 0));
  const leaderEnd = cmPos.clone().add(tauDir.clone().multiplyScalar(0.5));
  const cp = leaderStart.clone().lerp(leaderEnd, 0.5).add(new THREE.Vector3(0, -1.5, 0));
  const curve = new THREE.QuadraticBezierCurve3(leaderStart, cp, leaderEnd);
  const pts = curve.getPoints(15);
  leaderLine.geometry.setFromPoints(pts);
  leaderHead.position.copy(leaderEnd);
  leaderHead.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0), pts[15].clone().sub(pts[14]).normalize());

  const omegaLocal = new THREE.Vector3(1.2 * 0.707, 4.75, 1.2 * 0.707);
  lblOmega.pos.copy(omegaLocal).applyMatrix4(topGroup.matrixWorld);

  lblL.pos.copy(cmPos).add(lTip).multiplyScalar(0.5).add(new THREE.Vector3(0.4, 0, 0));
  lblLSin.pos.copy(circleCenter).add(lTip).multiplyScalar(0.5).add(new THREE.Vector3(0, 0.3, 0));
  lblDL.pos.copy(lTip).add(tauDir.clone().multiplyScalar(d.dLLen)).add(new THREE.Vector3(0.5, 0, 0));

  const midDPhi = lTip.clone().add(lTipFuture).multiplyScalar(0.5);
  lblDPhi.pos.copy(circleCenter).add(midDPhi.clone().sub(circleCenter).normalize().multiplyScalar(d.rad + 0.6));

  const thetaRad = THREE.MathUtils.degToRad(thetaDeg);
  lblTheta.pos.copy(toWorld(new THREE.Vector3(0, 2.8*Math.cos(thetaRad/2), 2.8*Math.sin(thetaRad/2))));

  const opMidAngle = (d.opStart + d.opEnd) / 2;
  lblOmegaP.pos.copy(toWorld(new THREE.Vector3(d.opRadius*Math.cos(opMidAngle), d.circleCenter_local.y, d.opRadius*Math.sin(opMidAngle)))).add(new THREE.Vector3(0, 0.5, 0));
}

