// @FIGURE_CODE_BEGIN
// 1) Define geometric constants and colors
const colorBlue = 0x7BAFD4;
const colorOrange = 0xF5B041;
const colorBrightOrange = 0xFF8C00;
const colorRed = 0xE63946;
const colorGreen = 0x2CA02C;

// 2) Basic thick arrow generator with emissive support
function createThickArrow(color, baseRadius=0.06, headRadius=0.15, headLength=0.4, useEmissive=false) {
  const group = new THREE.Group();
  const matOpts = { color, shininess: 60 };
  if (useEmissive) {
    matOpts.emissive = color;
    matOpts.emissiveIntensity = 0.5;
  }
  const mat = new THREE.MeshPhongMaterial(matOpts);

  const cyl = new THREE.Mesh(new THREE.CylinderGeometry(baseRadius, baseRadius, 1, 16), mat);
  const head = new THREE.Mesh(new THREE.ConeGeometry(headRadius, headLength, 16), mat);
  cyl.rotation.x = Math.PI / 2;
  cyl.position.set(0, 0, 0.5);
  head.rotation.x = Math.PI / 2;
  head.position.set(0, 0, 1);
  group.add(cyl);
  group.add(head);

  group.update = function(origin, dir, length) {
    if (length < 0.001) {
      this.visible = false;
      return;
    }
    this.visible = true;
    this.position.copy(origin);
    const q = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0,0,1), dir.clone().normalize());
    this.quaternion.copy(q);

    const cylLen = Math.max(0, length - headLength);
    cyl.scale.set(1, cylLen, 1);
    cyl.position.set(0, 0, cylLen / 2);
    head.position.set(0, 0, cylLen + headLength / 2);
  };
  return group;
}

function makeInteractive(arrowGroup, info) {
  arrowGroup.children.forEach(c => registerInteractive(c, info));
}

// 3) Setup Lights
const ambientLight = new THREE.AmbientLight(0xffffff, 0.8);
scene.add(ambientLight);
const dirLight = new THREE.DirectionalLight(0xffffff, 0.4);
dirLight.position.set(10, 15, 10);
scene.add(dirLight);
const dirLight2 = new THREE.DirectionalLight(0xffffff, 0.2);
dirLight2.position.set(-10, 5, -10);
scene.add(dirLight2);

// 4) Construct Top Geometry (Improved Conical Profile)
const ptsBlue1 = [], ptsOrange = [], ptsBlue2 = [];
for (let y = 0; y <= 1.8; y += 0.1) {
  // Sharp conical tip spreading outwards
  ptsBlue1.push(new THREE.Vector2( y * (1 + (2.5 - y) * 0.2), y ));
}
for (let y = 1.8; y <= 2.8; y += 0.1) {
  // Bulging middle
  let r = (y <= 2.5) ? y * (1 + (2.5 - y) * 0.2) : 2.5 - 1.2 * Math.pow((y - 2.5)/1.5, 2);
  ptsOrange.push(new THREE.Vector2( r, y ));
}
for (let y = 2.8; y <= 4.0; y += 0.1) {
  // Flatter top surface
  ptsBlue2.push(new THREE.Vector2( 2.5 - 1.2 * Math.pow((y - 2.5)/1.5, 2), y ));
}
ptsBlue2.push(new THREE.Vector2(0, 4.0)); // Cap the top

const matBlue = new THREE.MeshPhongMaterial({ color: colorBlue, shininess: 50 });
const matOrange = new THREE.MeshPhongMaterial({ color: colorOrange, shininess: 50 });

const topGroup = new THREE.Group();
const meshBlue1 = new THREE.Mesh(new THREE.LatheGeometry(ptsBlue1, 48), matBlue);
const meshOrange = new THREE.Mesh(new THREE.LatheGeometry(ptsOrange, 48), matOrange);
const meshBlue2 = new THREE.Mesh(new THREE.LatheGeometry(ptsBlue2, 48), matBlue);
const meshStem = new THREE.Mesh(new THREE.CylinderGeometry(0.35, 0.35, 1.5, 32), matBlue);
meshStem.position.set(0, 4.75, 0);
topGroup.add(meshBlue1, meshOrange, meshBlue2, meshStem);

// CM Marker (X) inside topGroup
const cmMarker = new THREE.Group();
const matBlack = new THREE.LineBasicMaterial({ color: 0x000000, linewidth: 2 });
cmMarker.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints([
  new THREE.Vector3(-0.3, 3, -0.3), new THREE.Vector3(0.3, 3, 0.3)
]), matBlack));
cmMarker.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints([
  new THREE.Vector3(-0.3, 3, 0.3), new THREE.Vector3(0.3, 3, -0.3)
]), matBlack));
topGroup.add(cmMarker);

// Omega (spin) arrow around stem
const omegaGroup = new THREE.Group();
const omegaCurvePts = [];
for (let i = 0; i <= 30; i++) {
  const a = (i/30) * Math.PI * 1.5; // CCW from +X
  omegaCurvePts.push(new THREE.Vector3(1.1 * Math.cos(a), 4.5, -1.1 * Math.sin(a)));
}
const omegaTube = new THREE.Mesh(new THREE.TubeGeometry(new THREE.CatmullRomCurve3(omegaCurvePts), 30, 0.04, 8, false), new THREE.MeshBasicMaterial({ color: colorGreen }));
const omegaHead = new THREE.Mesh(new THREE.ConeGeometry(0.12, 0.3, 8), new THREE.MeshBasicMaterial({ color: colorGreen }));
omegaHead.position.copy(omegaCurvePts[30]);
omegaHead.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0), omegaCurvePts[30].clone().sub(omegaCurvePts[29]).normalize());
omegaGroup.add(omegaTube, omegaHead);
topGroup.add(omegaGroup);

// Make top interactive
[meshBlue1, meshOrange, meshBlue2, meshStem].forEach(m => registerInteractive(m, { 
  title: "Spinning Top", 
  body: "The fast spin provides a large angular momentum L, which resists falling over." 
}));

// 5) Setup Scene Hierarchy and Elements
const precessionGroup = new THREE.Group();
scene.add(precessionGroup);
precessionGroup.add(topGroup);

const arrR = createThickArrow(0x222222, 0.05, 0.12, 0.4); precessionGroup.add(arrR);
const arrMg = createThickArrow(colorRed, 0.06, 0.15, 0.5, true); precessionGroup.add(arrMg);
const arrTau = createThickArrow(colorBrightOrange, 0.06, 0.15, 0.5, true); precessionGroup.add(arrTau);
const arrL = createThickArrow(colorBrightOrange, 0.06, 0.15, 0.5, true); precessionGroup.add(arrL);
const arrLSin = createThickArrow(colorBrightOrange, 0.05, 0.12, 0.4, true); precessionGroup.add(arrLSin);
const arrDL = createThickArrow(colorBrightOrange, 0.05, 0.12, 0.4, true); precessionGroup.add(arrDL);

makeInteractive(arrR, { title: "Position Vector (r)", body: "Vector from the origin to the center of mass (CM)." });
makeInteractive(arrMg, { title: "Gravitational Force (Mg)", body: "The downward pull of gravity acting on the CM." });
makeInteractive(arrTau, { title: "Torque (τ)", body: "The twisting force caused by gravity. It acts perpendicularly to both r and Mg." });
makeInteractive(arrL, { title: "Angular Momentum (L)", body: "The rotational momentum of the top. It aligns with the spin axis." });
makeInteractive(arrDL, { title: "Change in Angular Momentum (dL)", body: "Because the torque is perpendicular to L, it changes the direction of L without changing its magnitude." });

// Dashed circle and arcs in local frame
const dashedMat = new THREE.LineDashedMaterial({ color: 0x000000, dashSize: 0.2, gapSize: 0.2 });
const circlePts = [];
for (let i = 0; i <= 64; i++) {
  const a = (i/64) * Math.PI * 2;
  circlePts.push(new THREE.Vector3(Math.cos(a), 0, Math.sin(a)));
}
const circleLine = new THREE.Line(new THREE.BufferGeometry().setFromPoints(circlePts), dashedMat);
circleLine.computeLineDistances();
scene.add(circleLine); // In scene so it doesn't spin

const futureRadLine = new THREE.Line(new THREE.BufferGeometry(), dashedMat); precessionGroup.add(futureRadLine);
const thetaArcLine = new THREE.Line(new THREE.BufferGeometry(), new THREE.LineBasicMaterial({ color: 0x000000 })); precessionGroup.add(thetaArcLine);
const dPhiArcLine = new THREE.Line(new THREE.BufferGeometry(), new THREE.LineBasicMaterial({ color: 0x000000 })); precessionGroup.add(dPhiArcLine);

// Precession curved arrow (omega_p) in global scene
const omegaPGroup = new THREE.Group();
const omegaPHead = new THREE.Mesh(new THREE.ConeGeometry(0.12, 0.3, 8), new THREE.MeshBasicMaterial({ color: 0x000000 }));
omegaPGroup.add(omegaPHead);
scene.add(omegaPGroup);

// Leader line for Torque equation
const leaderGroup = new THREE.Group();
const leaderLine = new THREE.Line(new THREE.BufferGeometry(), new THREE.LineBasicMaterial({ color: 0x000000 }));
const leaderHead = new THREE.Mesh(new THREE.ConeGeometry(0.06, 0.2, 8), new THREE.MeshBasicMaterial({ color: 0x000000 }));
leaderGroup.add(leaderLine, leaderHead);
scene.add(leaderGroup);

// Stationary Axes matching source (Y=z, X=y, Z=x physically to let orbit controls work nicely)
const axisX = createThickArrow(0x000000, 0.02, 0.08, 0.2); scene.add(axisX); axisX.update(new THREE.Vector3(), new THREE.Vector3(1,0,0), 7);
const axisY = createThickArrow(0x000000, 0.02, 0.08, 0.2); scene.add(axisY); axisY.update(new THREE.Vector3(), new THREE.Vector3(0,1,0), 9);
const axisZ = createThickArrow(0x000000, 0.02, 0.08, 0.2); scene.add(axisZ); axisZ.update(new THREE.Vector3(), new THREE.Vector3(0,0,1), 7);

// 6) State variables and logic
let thetaDeg = 20;
let torqueMag = 1;
let phiDeg = 0;
let isPlaying = false;
let omegaPTubeMesh = null;

function rebuildGeometry() {
  const thetaRad = THREE.MathUtils.degToRad(thetaDeg);

  // Base tilt leans toward +X (textbook +y direction)
  const u_base = new THREE.Vector3(Math.sin(thetaRad), Math.cos(thetaRad), 0);
  topGroup.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0), u_base);

  const cmLocal = u_base.clone().multiplyScalar(3);
  arrR.update(new THREE.Vector3(), u_base, 3);
  arrMg.update(cmLocal, new THREE.Vector3(0,-1,0), 2.5);

  // tau = r x Mg. r=(3sin, 3cos, 0), Mg=(0, -2.5, 0) => tau = (0, 0, -7.5sin)
  const tauDirLocal = new THREE.Vector3(0,0,-1);
  const tauLen = 4 * torqueMag * Math.sin(thetaRad);
  arrTau.update(cmLocal, tauDirLocal, tauLen);

  arrL.update(cmLocal, u_base, 7);

  const lTipLocal = cmLocal.clone().add(u_base.clone().multiplyScalar(7));
  const circleCenterLocal = new THREE.Vector3(0, lTipLocal.y, 0);
  const rad = lTipLocal.x; // radius is purely in X due to local frame

  circleLine.position.set(0, lTipLocal.y, 0);
  circleLine.scale.set(rad, 1, rad);

  const radDirLocal = new THREE.Vector3(1, 0, 0);
  arrLSin.update(circleCenterLocal, radDirLocal, rad);

  const dLLen = 3 * torqueMag * Math.sin(thetaRad);
  arrDL.update(lTipLocal, tauDirLocal, dLLen);

  const lTipFutureLocal = lTipLocal.clone().add(tauDirLocal.clone().multiplyScalar(dLLen));
  futureRadLine.geometry.setFromPoints([circleCenterLocal, lTipFutureLocal]);
  futureRadLine.computeLineDistances();

  const dPhiPts = [];
  const endAngle = Math.atan2(-dLLen, lTipLocal.x); // Sweep towards -Z
  for(let i=0; i<=10; i++){
    const a = (i/10)*endAngle;
    dPhiPts.push(new THREE.Vector3(rad*Math.cos(a), lTipLocal.y, rad*Math.sin(a)));
  }
  dPhiArcLine.geometry.setFromPoints(dPhiPts);

  const thPts = [];
  for(let i=0; i<=15; i++){
    const t = (i/15)*thetaRad;
    thPts.push(new THREE.Vector3(2.5*Math.sin(t), 2.5*Math.cos(t), 0));
  }
  thetaArcLine.geometry.setFromPoints(thPts);

  // Precession global arrow (omega_p)
  const opRadius = rad + 1.2;
  const opStart = 1.15 * Math.PI; // Back-left
  const opEnd = 0.85 * Math.PI;   // Front-left
  const opPts = [];
  for(let i=0; i<=20; i++){
    const a = opStart + (i/20)*(opEnd - opStart);
    opPts.push(new THREE.Vector3(opRadius*Math.cos(a), lTipLocal.y, opRadius*Math.sin(a)));
  }
  if(omegaPTubeMesh) omegaPGroup.remove(omegaPTubeMesh);
  omegaPTubeMesh = new THREE.Mesh(new THREE.TubeGeometry(new THREE.CatmullRomCurve3(opPts), 20, 0.04, 8, false), new THREE.MeshBasicMaterial({ color: 0x000000 }));
  omegaPGroup.add(omegaPTubeMesh);
  omegaPHead.position.copy(opPts[20]);
  omegaPHead.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0), opPts[20].clone().sub(opPts[19]).normalize());

  window.__sceneData = { cmLocal, lTipLocal, lTipFutureLocal, circleCenterLocal, rad, endAngle, opRadius, opStart, opEnd };
}

// 7) Label Definitions and Updates
let lblX, lblY, lblZ, lblO, lblTheta, lblR, lblCM, lblMg, lblTau, lblTauEq, lblOmega, lblL, lblLSin, lblDL, lblDPhi, lblOmegaP;

function initLabels() {
  const fOpts = { fontSize: '16px', color: '#000' };
  lblX = addLabel('<i>y</i>', new THREE.Vector3(), fOpts);
  lblY = addLabel('<i>z</i>', new THREE.Vector3(), fOpts);
  lblZ = addLabel('<i>x</i>', new THREE.Vector3(), fOpts);
  lblO = addLabel('<i>O</i>', new THREE.Vector3(), fOpts);
  lblTheta = addLabel('<i>&theta;</i>', new THREE.Vector3(), fOpts);
  lblR = addLabel('<b>r</b>', new THREE.Vector3(), fOpts);
  lblCM = addLabel('CM', new THREE.Vector3(), fOpts);

  lblMg = addLabel('<i>M</i><b>g</b>', new THREE.Vector3(), { ...fOpts, color: '#' + colorRed.toString(16).padStart(6, '0') });
  lblTau = addLabel('<b>&tau;</b>', new THREE.Vector3(), { ...fOpts, color: '#' + colorBrightOrange.toString(16).padStart(6, '0') });
  lblTauEq = addLabel('<b>&tau;</b> = <b>r</b> &times; <i>M</i><b>g</b>', new THREE.Vector3(), fOpts);

  lblOmega = addLabel('<b>&omega;</b>', new THREE.Vector3(), { ...fOpts, color: '#' + colorGreen.toString(16).padStart(6, '0') });
  lblL = addLabel('<b>L</b>', new THREE.Vector3(), { ...fOpts, color: '#' + colorBrightOrange.toString(16).padStart(6, '0') });
