function updateLabels() {
  precessionGroup.rotation.y = THREE.MathUtils.degToRad(phiDeg);
  precessionGroup.updateMatrixWorld();

  lblX.pos.set(7.5, 0, 0); // physical X -> labeled 'y'
  lblY.pos.set(0, 9.5, 0); // physical Y -> labeled 'z'
  lblZ.pos.set(0, 0, 7.5); // physical Z -> labeled 'x'
  lblO.pos.set(0.1, -0.6, 0.1);

  const d = window.__sceneData;
  if (!d) return;

  const toWorld = (v) => v.clone().applyMatrix4(precessionGroup.matrixWorld);

  const cmPos = toWorld(d.cmLocal);
  const lTip = toWorld(d.lTipLocal);
  const lTipFuture = toWorld(d.lTipFutureLocal);
  const circleCenter = toWorld(d.circleCenterLocal);

  lblR.pos.copy(cmPos).multiplyScalar(0.5).add(new THREE.Vector3(0.4, 0, 0.4));
  lblCM.pos.copy(cmPos).add(new THREE.Vector3(-0.8, 0.2, -0.8));
  lblMg.pos.copy(cmPos).add(new THREE.Vector3(0, -1.8, 0));

  const tauTipLocal = d.cmLocal.clone().add(new THREE.Vector3(0, 0, -1).multiplyScalar(2.5)); // Approx tip for label
  lblTau.pos.copy(toWorld(tauTipLocal)).add(new THREE.Vector3(0, 0.5, 0));

  // Leader line for Torque equation
  const eqPos = cmPos.clone().add(new THREE.Vector3(4, -2.5, 2));
  lblTauEq.pos.copy(eqPos);

  const leaderStart = eqPos.clone().add(new THREE.Vector3(-0.6, 0.3, 0));
  const leaderEnd = cmPos.clone().add(toWorld(new THREE.Vector3(0, 0, -1)).sub(cmPos).normalize().multiplyScalar(0.8));
  const cp = leaderStart.clone().lerp(leaderEnd, 0.5).add(new THREE.Vector3(0, -1, 0));
  const curve = new THREE.QuadraticBezierCurve3(leaderStart, cp, leaderEnd);
  const pts = curve.getPoints(15);
  leaderLine.geometry.setFromPoints(pts);
  leaderHead.position.copy(leaderEnd);
  leaderHead.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0), pts[15].clone().sub(pts[14]).normalize());

  const omegaLocal = new THREE.Vector3(1.2 * 0.707, 4.5, -1.2 * 0.707);
  lblOmega.pos.copy(omegaLocal).applyMatrix4(topGroup.matrixWorld).add(new THREE.Vector3(0, 0.5, 0));

  lblL.pos.copy(cmPos).add(lTip).multiplyScalar(0.5).add(new THREE.Vector3(0.6, 0, 0));
  lblLSin.pos.copy(circleCenter).add(lTip).multiplyScalar(0.5).add(new THREE.Vector3(0, 0.4, 0));
  lblDL.pos.copy(lTipFuture).add(new THREE.Vector3(0.8, 0.3, 0));

  const midDPhi = lTip.clone().add(lTipFuture).multiplyScalar(0.5);
  lblDPhi.pos.copy(circleCenter).add(midDPhi.clone().sub(circleCenter).normalize().multiplyScalar(d.rad + 0.8));

  const thetaRad = THREE.MathUtils.degToRad(thetaDeg);
  lblTheta.pos.copy(toWorld(new THREE.Vector3(2.8*Math.sin(thetaRad/2), 2.8*Math.cos(thetaRad/2), 0)));

  const opMidAngle = (d.opStart + d.opEnd) / 2;
  lblOmegaP.pos.set(d.opRadius*Math.cos(opMidAngle), d.circleCenterLocal.y, d.opRadius*Math.sin(opMidAngle)).add(new THREE.Vector3(0, 0.6, 0));
}

