scene.add(dirLight);
const dirLight2 = new THREE.DirectionalLight(0xffffff, 0.2);
dirLight2.position.set(-5, 5, -5);
scene.add(dirLight2);

// 3) Construct Spinning Top
const ptsBlue1 = [], ptsOrange = [], ptsBlue2 = [];
