ptsBlue2.push(new THREE.Vector2(0, 3.2));

const matBlue = new THREE.MeshPhongMaterial({ color: colorBlue, shininess: 40, transparent: true, opacity: 0.85 });
const matOrange = new THREE.MeshPhongMaterial({ color: colorBand, shininess: 40, transparent: true, opacity: 0.85 });

const topGroup = new THREE.Group();
const meshBlue1 = new THREE.Mesh(new THREE.LatheGeometry(ptsBlue1, 48), matBlue);
const meshOrange = new THREE.Mesh(new THREE.LatheGeometry(ptsOrange, 48), matOrange);
const meshBlue2 = new THREE.Mesh(new THREE.LatheGeometry(ptsBlue2, 48), matBlue);
const meshStem = new THREE.Mesh(new THREE.CylinderGeometry(0.35, 0.35, 1.2, 32), matBlue);
meshStem.position.set(0, 3.7, 0); // CM at 3.0, flat top at 3.2, stem goes 3.1 to 4.3
topGroup.add(meshBlue1, meshOrange, meshBlue2, meshStem);
scene.add(topGroup);

const cmMarker = new THREE.Group();
const matBlack = new THREE.LineBasicMaterial({ color: 0x000000, linewidth: 2, depthTest: false, transparent: true });
const cmSize = 0.15;
cmMarker.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints([
  new THREE.Vector3(-cmSize, 3.0, -cmSize), new THREE.Vector3(cmSize, 3.0, cmSize)
]), matBlack));
cmMarker.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints([
  new THREE.Vector3(-cmSize, 3.0, cmSize), new THREE.Vector3(cmSize, 3.0, -cmSize)
]), matBlack));
topGroup.add(cmMarker);

const omegaGroup = new THREE.Group();
const omegaCurvePts = [];
for (let i = 0; i <= 30; i++) {
  const a = (i/30) * Math.PI * 1.5; 
  omegaCurvePts.push(new THREE.Vector3(1.0 * Math.cos(a), 3.8, 1.0 * Math.sin(a))); // CCW
}
const omegaTube = new THREE.Mesh(new THREE.TubeGeometry(new THREE.CatmullRomCurve3(omegaCurvePts), 30, 0.03, 8, false), new THREE.MeshBasicMaterial({ color: colorGreen }));
const omegaHead = new THREE.Mesh(new THREE.ConeGeometry(0.1, 0.25, 8), new THREE.MeshBasicMaterial({ color: colorGreen }));
omegaHead.position.copy(omegaCurvePts[30]);
omegaHead.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0), omegaCurvePts[30].clone().sub(omegaCurvePts[29]).normalize());
omegaGroup.add(omegaTube, omegaHead);
topGroup.add(omegaGroup);

[meshBlue1, meshOrange, meshBlue2, meshStem].forEach(m => registerInteractive(m, { 
  title: "Spinning Top", 
  body: "The fast spin provides a large angular momentum L, which resists falling over." 
}));

// 4) Vectors and Lines
const arrR = createThickArrow(0x222222, 0.04, 0.10, 0.3); scene.add(arrR);
const arrMg = createThickArrow(colorRed, 0.05, 0.12, 0.35, true); scene.add(arrMg);
const arrTau = createThickArrow(colorOrange, 0.05, 0.12, 0.35, true); scene.add(arrTau);
const arrL = createThickArrow(colorOrange, 0.05, 0.12, 0.35, true); scene.add(arrL);
const arrLSin = createThickArrow(colorOrange, 0.04, 0.10, 0.3, true); scene.add(arrLSin);
const arrDL = createThickArrow(colorOrange, 0.04, 0.10, 0.3, true); scene.add(arrDL);

makeInteractive(arrR, { title: "Position Vector (r)", body: "Vector from the origin to the center of mass (CM)." });
makeInteractive(arrMg, { title: "Gravitational Force (Mg)", body: "The downward pull of gravity acting on the CM." });
makeInteractive(arrTau, { title: "Torque (τ)", body: "The twisting force caused by gravity. It acts perpendicularly to both r and Mg." });
makeInteractive(arrL, { title: "Angular Momentum (L)", body: "The rotational momentum of the top. It aligns with the spin axis." });
makeInteractive(arrDL, { title: "Change in Angular Momentum (dL)", body: "Because the torque is perpendicular to L, it changes the direction of L without changing its magnitude." });
makeInteractive(arrLSin, { title: "Horizontal Angular Momentum", body: "The projection of L onto the horizontal plane, L sin(θ)." });

const dashedMat = new THREE.LineDashedMaterial({ color: 0x000000, dashSize: 0.15, gapSize: 0.15 });
const circleLine = new THREE.Line(new THREE.BufferGeometry(), dashedMat); scene.add(circleLine);
const futureRadLine = new THREE.Line(new THREE.BufferGeometry(), dashedMat); scene.add(futureRadLine);
const dPhiArcLine = new THREE.Line(new THREE.BufferGeometry(), new THREE.LineDashedMaterial({ color: 0x000000, dashSize: 0.06, gapSize: 0.06 })); scene.add(dPhiArcLine);
const thetaArcLine = new THREE.Line(new THREE.BufferGeometry(), new THREE.LineBasicMaterial({ color: 0x000000 })); scene.add(thetaArcLine);

const omegaPGroup = new THREE.Group();
const omegaPHead = new THREE.Mesh(new THREE.ConeGeometry(0.1, 0.25, 8), new THREE.MeshBasicMaterial({ color: 0x000000 }));
omegaPGroup.add(omegaPHead);
scene.add(omegaPGroup);

const leaderGroup = new THREE.Group();
const leaderLine = new THREE.Line(new THREE.BufferGeometry(), new THREE.LineBasicMaterial({ color: 0x000000, depthTest: false }));
const leaderHead = new THREE.Mesh(new THREE.ConeGeometry(0.06, 0.15, 8), new THREE.MeshBasicMaterial({ color: 0x000000, depthTest: false }));
leaderGroup.add(leaderLine, leaderHead);
scene.add(leaderGroup);

const axisX = createThickArrow(0x000000, 0.02, 0.08, 0.2); scene.add(axisX); axisX.update(new THREE.Vector3(), new THREE.Vector3(1,0,0), 4);
const axisY = createThickArrow(0x000000, 0.02, 0.08, 0.2); scene.add(axisY); axisY.update(new THREE.Vector3(), new THREE.Vector3(0,1,0), 4);
const axisZ = createThickArrow(0x000000, 0.02, 0.08, 0.2); scene.add(axisZ); axisZ.update(new THREE.Vector3(), new THREE.Vector3(0,0,1), 4);

// 5) State variables and logic
let thetaDeg = 20;
let phiDeg = 30; // initial azimuthal angle (forward-right)
let torqueMag = 1;
let isPlaying = false;
let omegaPTubeMesh = null;

function rebuildGeometry() {
  const theta = THREE.MathUtils.degToRad(thetaDeg);
  const phi = THREE.MathUtils.degToRad(phiDeg);

  const u = new THREE.Vector3(
    Math.sin(theta) * Math.sin(phi),
    Math.cos(theta),
    Math.sin(theta) * Math.cos(phi)
  );

  topGroup.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), u);

  const cm = u.clone().multiplyScalar(3.0);
  arrR.update(new THREE.Vector3(), u, 3.0);
  arrMg.update(cm, new THREE.Vector3(0, -1, 0), 1.5);

  const tauDir = new THREE.Vector3(u.z, 0, -u.x).normalize();
  const tauLen = 1.2 * torqueMag * Math.sin(theta);
  arrTau.update(cm, tauDir, tauLen);

  const lLen = 4.0;
  arrL.update(cm, u, lLen);

  const lTip = cm.clone().add(u.clone().multiplyScalar(lLen));
  const circleCenter = new THREE.Vector3(0, lTip.y, 0);
  const rad = 4.0 * Math.sin(theta); // L length is 4.0

  const cPts = [];
  for (let i = 0; i <= 64; i++) {
    const a = (i/64) * Math.PI * 2;
    cPts.push(new THREE.Vector3(rad * Math.cos(a), lTip.y, rad * Math.sin(a)));
  }
  circleLine.geometry.setFromPoints(cPts);
  circleLine.computeLineDistances();

  const radDir = lTip.clone().sub(circleCenter).normalize();
  arrLSin.update(circleCenter, radDir, rad);

  const dLLen = tauLen; // dL = tau dt visually
  arrDL.update(lTip, tauDir, dLLen);

  const lTipFuture = lTip.clone().add(tauDir.clone().multiplyScalar(dLLen));
  futureRadLine.geometry.setFromPoints([circleCenter, lTipFuture]);
  futureRadLine.computeLineDistances();

  const dPhiPts = [];
  const aStart = Math.PI / 2 - phi;
  const dphi = dLLen / rad; 
  for (let i = 0; i <= 10; i++) {
    const a = aStart - (i/10) * dphi;
    dPhiPts.push(new THREE.Vector3(rad * Math.cos(a), lTip.y, rad * Math.sin(a)));
  }
  dPhiArcLine.geometry.setFromPoints(dPhiPts);
  dPhiArcLine.computeLineDistances();

  const thPts = [];
  for (let i = 0; i <= 15; i++) {
    const t = (i/15) * theta;
    thPts.push(new THREE.Vector3(
      1.5 * Math.sin(t) * Math.sin(phi),
      1.5 * Math.cos(t),
      1.5 * Math.sin(t) * Math.cos(phi)
    ));
  }
  thetaArcLine.geometry.setFromPoints(thPts);

  const opRadius = rad + 0.6;
  const opPts = [];
  const opMid = Math.PI / 2 - (phi + Math.PI); // Opposite side of circle
  for (let i = 0; i <= 20; i++) {
    const a = opMid + 0.25 * Math.PI - (i/20) * 0.5 * Math.PI; 
    opPts.push(new THREE.Vector3(opRadius * Math.cos(a), lTip.y, opRadius * Math.sin(a)));
  }
  if (omegaPTubeMesh) omegaPGroup.remove(omegaPTubeMesh);
  omegaPTubeMesh = new THREE.Mesh(
    new THREE.TubeGeometry(new THREE.CatmullRomCurve3(opPts), 20, 0.03, 8, false),
    new THREE.MeshBasicMaterial({ color: 0x000000 })
  );
  omegaPGroup.add(omegaPTubeMesh);
  omegaPHead.position.copy(opPts[20]);
  omegaPHead.quaternion.setFromUnitVectors(
    new THREE.Vector3(0, 1, 0),
    opPts[20].clone().sub(opPts[19]).normalize()
  );

  window.__sceneData = { u, cm, lTip, lTipFuture, circleCenter, rad, tauDir, aStart, dphi, opRadius, opMid };
}

