  lblZ = addLabel('<i>x</i>', new THREE.Vector3(), fOpts);
  lblO = addLabel('<i>O</i>', new THREE.Vector3(), fOpts);
  lblTheta = addLabel('<i>&theta;</i>', new THREE.Vector3(), fOpts);
  lblR = addLabel('<b>r</b>', new THREE.Vector3(), fOpts);
  lblCM = addLabel('CM', new THREE.Vector3(), fOpts);
  lblMg = addLabel('<i>M</i><b>g</b>', new THREE.Vector3(), { ...fOpts, color: '#' + colorRed.toString(16).padStart(6, '0') });
  lblTau = addLabel('<b>&tau;</b>', new THREE.Vector3(), { ...fOpts, color: '#' + colorOrange.toString(16).padStart(6, '0') });
  lblTauEq = addLabel('<b>&tau;</b> = <b>r</b> &times; <i>M</i><b>g</b>', new THREE.Vector3(), fOpts);
  lblOmega = addLabel('<b>&omega;</b>', new THREE.Vector3(), { ...fOpts, color: '#' + colorGreen.toString(16).padStart(6, '0') });
  lblL = addLabel('<b>L</b>', new THREE.Vector3(), { ...fOpts, color: '#' + colorOrange.toString(16).padStart(6, '0') });
  lblLSin = addLabel('<i>L</i> sin <i>&theta;</i>', new THREE.Vector3(), fOpts);
  lblDL = addLabel('<i>d</i><b>L</b> = <b>&tau;</b> <i>dt</i>', new THREE.Vector3(), fOpts);
  lblDPhi = addLabel('<i>d&phi;</i>', new THREE.Vector3(), fOpts);
  lblOmegaP = addLabel('<b>&omega;</b><sub><i>p</i></sub>', new THREE.Vector3(), fOpts);
}

function updateLabels() {
  lblX.pos.set(0, 0, 4.3);
  lblY.pos.set(4.3, 0, 0);
  lblZ.pos.set(0, 4.3, 0);
  lblO.pos.set(-0.2, -0.4, 0.2);

  const d = window.__sceneData;
  if (!d) return;

  lblR.pos.copy(d.cm).multiplyScalar(0.5).add(new THREE.Vector3(0.2, -0.1, 0.2));
  lblCM.pos.copy(d.cm).add(new THREE.Vector3(-0.4, 0.2, 0));
  lblMg.pos.copy(d.cm).add(new THREE.Vector3(0.2, -0.75, 0));

  lblTau.pos.copy(d.cm).add(d.tauDir.clone().multiplyScalar(1.2 * torqueMag * Math.sin(THREE.MathUtils.degToRad(thetaDeg)))).add(new THREE.Vector3(0, 0.2, 0));

  const eqPos = d.cm.clone().add(new THREE.Vector3(1.5, -1.0, 0.5));
  lblTauEq.pos.copy(eqPos);

  const leaderStart = eqPos.clone().add(new THREE.Vector3(-0.1, 0.1, 0));
  const leaderEnd = d.cm.clone().add(d.tauDir.clone().multiplyScalar(0.5));
  const cp = leaderStart.clone().lerp(leaderEnd, 0.5).add(new THREE.Vector3(0, -0.6, 0));
  const curve = new THREE.QuadraticBezierCurve3(leaderStart, cp, leaderEnd);
  const pts = curve.getPoints(15);
  leaderLine.geometry.setFromPoints(pts);
  leaderHead.position.copy(leaderEnd);
  leaderHead.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), pts[15].clone().sub(pts[14]).normalize());

  lblOmega.pos.copy(d.cm).add(d.u.clone().multiplyScalar(0.8)).add(new THREE.Vector3(-0.6, 0.2, 0));
  lblL.pos.copy(d.cm).add(d.u.clone().multiplyScalar(2.0)).add(new THREE.Vector3(0.3, 0, 0));
  lblLSin.pos.copy(d.circleCenter).add(d.lTip).multiplyScalar(0.5).add(new THREE.Vector3(0, 0.2, 0));
  lblDL.pos.copy(d.lTipFuture).add(new THREE.Vector3(0.2, 0.2, 0.2));

  const aMid = d.aStart - d.dphi / 2;
  const midDir = new THREE.Vector3(Math.cos(aMid), 0, Math.sin(aMid));
  lblDPhi.pos.copy(d.circleCenter).add(midDir.multiplyScalar(d.rad + 0.3)).add(new THREE.Vector3(0, 0.1, 0));

  const thetaRad = THREE.MathUtils.degToRad(thetaDeg);
  const phiRad = THREE.MathUtils.degToRad(phiDeg);
  lblTheta.pos.set(
    1.6 * Math.sin(thetaRad/2) * Math.sin(phiRad),
    1.6 * Math.cos(thetaRad/2),
    1.6 * Math.sin(thetaRad/2) * Math.cos(phiRad)
  );

  lblOmegaP.pos.set(
    (d.opRadius + 0.3) * Math.cos(d.opMid),
    d.lTip.y,
    (d.opRadius + 0.3) * Math.sin(d.opMid)
  ).add(new THREE.Vector3(0, 0.4, 0));
}

initLabels();
rebuildGeometry();
updateLabels();
setCameraView({ projection: 'perspective', azimuthDeg: 35, elevationDeg: 20, rollDeg: 0, heightFraction: 0.7 });

// 7) UI and Animation
const btnPrecession = document.getElementById('precession');
btnPrecession.addEventListener('click', () => {
  isPlaying = !isPlaying;
  btnPrecession.textContent = isPlaying ? 'Pause Precession' : 'Play Precession';
  btnPrecession.classList.toggle('active', isPlaying);
});

const inTheta = document.getElementById('theta');
const valTheta = document.getElementById('theta-val');
inTheta.addEventListener('input', (e) => {
  thetaDeg = parseFloat(e.target.value);
  valTheta.innerHTML = thetaDeg + '&deg;';
  rebuildGeometry();
  updateLabels();
});

const inTorque = document.getElementById('torqueMag');
const valTorque = document.getElementById('torqueMag-val');
inTorque.addEventListener('input', (e) => {
  torqueMag = parseFloat(e.target.value);
  valTorque.textContent = torqueMag.toFixed(1);
  rebuildGeometry();
  updateLabels();
});

window.goToStep = function(step) {
  if (step.state) {
    if (step.state.theta !== undefined) {
      thetaDeg = step.state.theta;
      inTheta.value = thetaDeg;
      valTheta.innerHTML = thetaDeg + '&deg;';
    }
    if (step.state.torqueMag !== undefined) {
      torqueMag = step.state.torqueMag;
      inTorque.value = torqueMag;
      valTorque.textContent = torqueMag.toFixed(1);
    }
    rebuildGeometry();
    updateLabels();
  }
};

let myLastTime = performance.now();
function customUpdate() {
  requestAnimationFrame(customUpdate);
  const now = performance.now();
  const dt = (now - myLastTime) / 1000;
  myLastTime = now;

  if (isPlaying) {
    phiDeg += 40 * dt * torqueMag; 
    if (phiDeg >= 360) phiDeg -= 360;
    rebuildGeometry();
    updateLabels();
  }
}
customUpdate();
// @FIGURE_CODE_END

